import React from 'react';
import { clsx } from 'clsx';

interface GlassCardProps {
  children: React.ReactNode;
  className?: string;
  hoverEffect?: boolean;
  onClick?: () => void;
}

export const GlassCard: React.FC<GlassCardProps> = ({ 
  children, 
  className, 
  hoverEffect = false,
  onClick 
}) => {
  return (
    <div 
      onClick={onClick}
      className={clsx(
        "relative overflow-hidden rounded-2xl border border-white/10 bg-[#121212]/60 backdrop-blur-md shadow-xl",
        hoverEffect && "transition-all duration-300 hover:bg-[#1a1a1a]/80 hover:border-[#00FFFF]/30 hover:shadow-[0_0_20px_rgba(0,255,255,0.1)] hover:-translate-y-1 cursor-pointer",
        className
      )}
    >
      {/* Noise texture overlay (optional, simulating via gradient for now) */}
      <div className="absolute inset-0 bg-gradient-to-br from-white/5 to-transparent pointer-events-none" />
      <div className="relative z-10 p-6">
        {children}
      </div>
    </div>
  );
};
